<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserProfile\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Access\UserProfile\Domain\ValueObject\UserProfileUserVO;
use Civi\Lughauth\Features\Access\User\Domain\UserRef;

trait UserProfileUserAccessor
{
    private UserProfileUserVO $_user;
    public function getUser(): UserRef
    {
        return $this->_user->value();
    }
    public function user(): UserProfileUserVO
    {
        return $this->_user;
    }
    public function isUserChanged(?self $original = null): bool
    {
        return !$this->_user->equals($original?->_user);
    }
    public function withUser(UserProfileUserVO|UserRef $user): self
    {
        $copy = clone $this;
        $copy->_user = UserProfileUserVO::from($user);
        return $copy;
    }
}
